"use client";

import { useState, useEffect } from "react";
import { logger } from '@/lib/logger';
import { useSession } from "next-auth/react";
import { TrendingUp, Award, Clock, Target, CheckCircle, BookOpen, Trophy, Loader2 } from "lucide-react";
import { getUserAggregateProgressAction, calculateStreakAction } from "@/app/actions/academy";
import BackButton from "@/components/ui/BackButton";

export default function ProgressPage() {
    const { data: session } = useSession();
    const [loading, setLoading] = useState(true);
    const [userId, setUserId] = useState<string | null>(null);
    const [progressData, setProgressData] = useState({
        totalCourses: 0,
        completedCourses: 0,
        inProgressCourses: 0,
        totalHoursLearned: 0,
        certificatesEarned: 0,
        currentStreak: 0, // Streak tracking requires activity log collection - can be added post-launch
        totalLessons: 0,
        completedLessons: 0,
        overallProgress: 0,
    });

    useEffect(() => {
        if (session?.user?.id) {
            setUserId(session.user.id);
        }
    }, [session]);

    useEffect(() => {
        async function loadProgress() {
            if (!userId) return;

            setLoading(true);
            try {
                const [data, { streak }] = await Promise.all([
                    getUserAggregateProgressAction(userId),
                    calculateStreakAction(userId),
                ]);
                setProgressData({
                    ...data,
                    currentStreak: streak,
                });
            } catch (error) {
                logger.error("Failed to load progress:", error);
            } finally {
                setLoading(false);
            }
        }

        loadProgress();
    }, [userId]);

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-12 h-12 animate-spin text-blue-600" />
            </div>
        );
    }

    return (
        <div className="space-y-8">
            {/* Header */}
            <div>
                <BackButton fallbackPath="/academy/dashboard" />
                <h1 className="text-3xl font-bold text-slate-900 mb-2">
                    Learning Progress
                </h1>
                <p className="text-slate-600">
                    Track your achievements and learning milestones
                </p>
            </div>

            {/* Overview Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-white rounded-xl p-6 border border-slate-200">
                    <div className="flex flex-col items-center text-center">
                        <div className="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center mb-3">
                            <BookOpen className="w-6 h-6 text-blue-600" />
                        </div>
                        <p className="text-2xl font-bold text-slate-900">
                            {progressData.totalCourses}
                        </p>
                        <p className="text-sm text-slate-600">Total Courses</p>
                    </div>
                </div>

                <div className="bg-white rounded-xl p-6 border border-slate-200">
                    <div className="flex flex-col items-center text-center">
                        <div className="w-12 h-12 bg-green-100 rounded-lg flex items-center justify-center mb-3">
                            <CheckCircle className="w-6 h-6 text-green-600" />
                        </div>
                        <p className="text-2xl font-bold text-slate-900">
                            {progressData.completedCourses}
                        </p>
                        <p className="text-sm text-slate-600">Completed</p>
                    </div>
                </div>

                <div className="bg-white rounded-xl p-6 border border-slate-200">
                    <div className="flex flex-col items-center text-center">
                        <div className="w-12 h-12 bg-yellow-100 rounded-lg flex items-center justify-center mb-3">
                            <Award className="w-6 h-6 text-yellow-600" />
                        </div>
                        <p className="text-2xl font-bold text-slate-900">
                            {progressData.certificatesEarned}
                        </p>
                        <p className="text-sm text-slate-600">Certificates</p>
                    </div>
                </div>

                <div className="bg-white rounded-xl p-6 border border-slate-200">
                    <div className="flex flex-col items-center text-center">
                        <div className="w-12 h-12 bg-orange-100 rounded-lg flex items-center justify-center mb-3">
                            <Clock className="w-6 h-6 text-orange-600" />
                        </div>
                        <p className="text-2xl font-bold text-slate-900">
                            {Math.round(progressData.totalHoursLearned)}h
                        </p>
                        <p className="text-sm text-slate-600">Learning Time</p>
                    </div>
                </div>
            </div>

            {/* Overall Progress */}
            <div className="bg-white rounded-xl p-6 border border-slate-200">
                <div className="flex items-center justify-between mb-4">
                    <h2 className="text-xl font-bold text-slate-900">Overall Progress</h2>
                    <span className="text-2xl font-bold text-blue-600">{progressData.overallProgress}%</span>
                </div>
                <div className="h-4 bg-slate-200 rounded-full overflow-hidden mb-2">
                    <div
                        className="h-2 bg-linear-to-r from-primary to-blue-500 rounded-full transition-all"
                        style={{ width: `${progressData.overallProgress}%` }}
                    />
                </div>
                <p className="text-sm text-slate-600">
                    {progressData.completedLessons} of {progressData.totalLessons} lessons completed
                </p>
            </div>

            {/* Empty State or Stats */}
            {progressData.totalCourses === 0 ? (
                <div className="bg-white rounded-xl p-12 border border-slate-200 text-center">
                    <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-6">
                        <BookOpen className="w-10 h-10 text-slate-400" />
                    </div>
                    <h3 className="text-xl font-semibold text-slate-900 mb-2">
                        No Courses Enrolled
                    </h3>
                    <p className="text-slate-600 mb-6 max-w-md mx-auto">
                        Start your learning journey by enrolling in courses from our Academy catalog
                    </p>
                    <a
                        href="/academy"
                        className="inline-flex items-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition-colors"
                    >
                        <BookOpen className="w-5 h-5" />
                        Browse Courses
                    </a>
                </div>
            ) : (
                <>
                    {/* Course Stats */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="bg-white rounded-xl p-6 border border-slate-200">
                            <div className="flex items-center gap-3 mb-4">
                                <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
                                    <TrendingUp className="w-5 h-5 text-blue-600" />
                                </div>
                                <h3 className="font-bold text-slate-900">In Progress</h3>
                            </div>
                            <p className="text-3xl font-bold text-slate-900 mb-1">
                                {progressData.inProgressCourses}
                            </p>
                            <p className="text-sm text-slate-600">
                                Courses currently learning
                            </p>
                        </div>

                        <div className="bg-white rounded-xl p-6 border border-slate-200">
                            <div className="flex items-center gap-3 mb-4">
                                <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
                                    <Trophy className="w-5 h-5 text-green-600" />
                                </div>
                                <h3 className="font-bold text-slate-900">Completion Rate</h3>
                            </div>
                            <p className="text-3xl font-bold text-slate-900 mb-1">
                                {progressData.totalCourses > 0
                                    ? Math.round((progressData.completedCourses / progressData.totalCourses) * 100)
                                    : 0}%
                            </p>
                            <p className="text-sm text-slate-600">
                                {progressData.completedCourses} of {progressData.totalCourses} completed
                            </p>
                        </div>
                    </div>

                    {/* Info Card */}
                    <div className="bg-linear-to-br from-blue-50 to-indigo-50 border border-blue-200 rounded-2xl p-6">
                        <div className="flex gap-4">
                            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center shrink-0">
                                <Target className="w-6 h-6 text-white" />
                            </div>
                            <div>
                                <h4 className="font-semibold text-slate-900 mb-2">
                                    Keep Learning!
                                </h4>
                                <p className="text-sm text-slate-900">
                                    You&apos;re making great progress! Complete lessons to unlock certificates and advance your career in agribusiness.
                                </p>
                            </div>
                        </div>
                    </div>
                </>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { getPropertiesAction, deletePropertyAction, Property } from "@/app/actions/farm-nation";
import { useAdminData } from "@/hooks/useAdminData";
import AdminDataTable from "@/components/admin/AdminDataTable";
import { useToast } from "@/contexts/ToastContext";
import { MapPin, ArrowUpRight, Trash2, Loader2, Link as LinkIcon, Eye } from "lucide-react";
import Link from "next/link";

export default function FarmNationListingsPage() {
    const { showToast } = useToast();
    const [processingId, setProcessingId] = useState<string | null>(null);

    const {
        data: properties,
        loading,
        error,
        search,
        setSearch,
        filters,
        updateFilter,
        hasMore,
        onNextPage,
        onPrevPage,
        pageIndex,
        setData
    } = useAdminData<Property>({
        fetchAction: async (params) => {
            // Adapt params for getPropertiesAction
            // Note: getPropertiesAction needs an update to support pagination/search if it doesn't already
            // For now we pass standard params, assuming we will update action next
            return await getPropertiesAction(params);
        },
        limit: 20
    });

    const handleDelete = async (id: string) => {
        if (!confirm("Are you sure you want to delete this listing?")) return;
        setProcessingId(id);

        const result = await deletePropertyAction(id);
        if (result.success) {
            setData(prev => prev.filter(p => p.id !== id));
            showToast("Property deleted successfully", "success");
        } else {
            showToast(result.error || "Failed to delete property", "error");
        }
        setProcessingId(null);
    };

    const columns = [
        {
            header: "Property",
            accessor: (item: Property) => (
                <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-lg bg-slate-100 overflow-hidden shrink-0">
                        {item.images?.[0] ? (
                            <img src={item.images[0]} alt={item.name} className="w-full h-full object-cover" />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center text-slate-400">
                                <MapPin className="w-5 h-5" />
                            </div>
                        )}
                    </div>
                    <div>
                        <div className="font-bold text-slate-900 line-clamp-1">{item.name}</div>
                        <div className="text-xs text-slate-500">{item.location}, {item.state}</div>
                    </div>
                </div>
            )
        },
        {
            header: "Type",
            accessor: (item: Property) => (
                <div className="space-y-1">
                    <span className={`px-2 py-0.5 rounded-full text-xs font-bold uppercase ${item.type === "sale" ? "bg-blue-100 text-blue-700" : "bg-purple-100 text-purple-700"
                        }`}>
                        {item.type}
                    </span>
                    <div className="text-xs text-slate-500 capitalize">{item.category?.replace("farming-", "")}</div>
                </div>
            ),
            hideOnMobile: true
        },
        {
            header: "Price",
            accessor: (item: Property) => (
                <div>
                    <div className="font-bold text-green-600">
                        ₦{item.price.toLocaleString()}
                    </div>
                    {item.size && <div className="text-xs text-slate-500">{item.size} Acres</div>}
                </div>
            )
        },
        {
            header: "Owner",
            accessor: (item: Property) => (
                <div className="text-sm">
                    <div className="text-slate-900">{item.ownerName}</div>
                    <div className="text-slate-500 text-xs">{item.ownerEmail}</div>
                </div>
            ),
            hideOnMobile: true
        },
        {
            header: "Status",
            accessor: (item: Property) => (
                <span className={`px-2 py-1 rounded-full text-xs font-bold capitalize ${item.status === "available" ? "bg-green-100 text-green-700" :
                        item.status === "pending" ? "bg-yellow-100 text-yellow-700" :
                            item.status === "sold" ? "bg-slate-100 text-slate-700" :
                                "bg-red-100 text-red-700"
                    }`}>
                    {item.status}
                </span>
            )
        },
        {
            header: "Actions",
            accessor: (item: Property) => (
                <div className="flex items-center gap-2 justify-end">
                    <Link
                        href={`/farm-nation/property/${item.id}`}
                        target="_blank"
                        className="p-1.5 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition"
                    >
                        <ArrowUpRight className="w-4 h-4" />
                    </Link>
                    <button
                        onClick={(e) => { e.stopPropagation(); handleDelete(item.id); }}
                        disabled={processingId === item.id}
                        className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition disabled:opacity-50"
                    >
                        {processingId === item.id ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                    </button>
                </div>
            )
        }
    ];

    return (
        <div className="min-h-screen bg-slate-50 p-4 sm:p-8">
            <div className="mb-6 sm:mb-8 flex items-center justify-between">
                <div>
                    <h1 className="text-2xl sm:text-3xl font-bold text-slate-900 mb-2">
                        Property Listings
                    </h1>
                    <p className="text-sm sm:text-base text-slate-600">
                        Manage Farm Nation property listings
                    </p>
                </div>
                <Link
                    href="/farm-nation/listing/new"
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition hidden sm:block"
                >
                    Create Listing
                </Link>
            </div>

            <AdminDataTable
                columns={columns}
                data={properties}
                loading={loading}
                error={error}
                searchTerm={search}
                onSearch={setSearch}
                hasMore={hasMore}
                onNextPage={onNextPage}
                onPrevPage={onPrevPage}
                pageIndex={pageIndex}
                filters={
                    <>
                        <select
                            value={filters.type || "all"}
                            onChange={(e) => updateFilter("type", e.target.value)}
                            className="px-3 py-2 rounded-lg border border-slate-300 bg-white text-sm"
                        >
                            <option value="all">All Types</option>
                            <option value="sale">For Sale</option>
                            <option value="lease">For Lease</option>
                        </select>
                        <select
                            value={filters.status || "all"}
                            onChange={(e) => updateFilter("status", e.target.value)}
                            className="px-3 py-2 rounded-lg border border-slate-300 bg-white text-sm"
                        >
                            <option value="all">All Status</option>
                            <option value="available">Available</option>
                            <option value="pending">Pending</option>
                            <option value="sold">Sold</option>
                        </select>
                    </>
                }
            />
        </div>
    );
}

